using System;
using System.Runtime.InteropServices;
using System.Security;
using System.Security.Cryptography;
using System.Text;
using System.Collections.Concurrent;

namespace SecureDb.Driver
{
    /// <summary>
    /// Native interop layer for cross-service authentication tokens.
    /// Uses platform-specific crypto acceleration via JNI bridge on Linux
    /// and CNG on Windows for HMAC-based service identity verification.
    /// </summary>
    internal static class NativeAuthBridge
    {
        private const string NativeLib = "libsecuredb_auth";

        [DllImport(NativeLib, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sdb_derive_session_key(
            byte[] masterKey, int masterKeyLen,
            byte[] context, int contextLen,
            byte[] output, int outputLen);

        [DllImport(NativeLib, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sdb_verify_token(
            byte[] token, int tokenLen,
            byte[] key, int keyLen,
            byte[] nonce, int nonceLen);

        [DllImport(NativeLib, CallingConvention = CallingConvention.Cdecl)]
        private static extern int sdb_compute_auth_tag(
            byte[] payload, int payloadLen,
            byte[] key, int keyLen,
            byte[] tagOut, int tagOutLen);

        private static readonly ConcurrentDictionary<string, CachedSession> _sessionCache
            = new ConcurrentDictionary<string, CachedSession>();

        private class CachedSession
        {
            public byte[] DerivedKey { get; set; }
            public DateTime ExpiresAt { get; set; }
            public byte[] ServiceNonce { get; set; }
        }

        /// <summary>
        /// Authenticates a cross-service request by deriving a session key
        /// from the master credential and verifying the presented token.
        /// </summary>
        public static bool AuthenticateServiceRequest(
            string serviceId,
            byte[] masterCredential,
            byte[] presentedToken,
            byte[] requestPayload)
        {
            if (string.IsNullOrEmpty(serviceId))
                throw new ArgumentNullException(nameof(serviceId));
            if (masterCredential == null || masterCredential.Length < 32)
                throw new ArgumentException("Master credential must be at least 32 bytes");
            if (presentedToken == null || presentedToken.Length == 0)
                throw new ArgumentException("Token cannot be empty");

            var session = GetOrCreateSession(serviceId, masterCredential);

            // Verify the token against derived session key
            int verifyResult = sdb_verify_token(
                presentedToken, presentedToken.Length,
                session.DerivedKey, session.DerivedKey.Length,
                session.ServiceNonce, session.ServiceNonce.Length);

            if (verifyResult != 0)
                return false;

            // Compute auth tag over the request payload for integrity
            byte[] computedTag = new byte[32];
            int tagResult = sdb_compute_auth_tag(
                requestPayload, requestPayload.Length,
                session.DerivedKey, session.DerivedKey.Length,
                computedTag, computedTag.Length);

            if (tagResult != 0)
                return false;

            // Extract the embedded tag from the token (last 32 bytes)
            if (presentedToken.Length < 64)
                return false;

            byte[] embeddedTag = new byte[32];
            Buffer.BlockCopy(presentedToken, presentedToken.Length - 32, embeddedTag, 0, 32);

            return ConstantTimeEquals(computedTag, embeddedTag);
        }

        private static CachedSession GetOrCreateSession(string serviceId, byte[] masterCredential)
        {
            if (_sessionCache.TryGetValue(serviceId, out var existing))
            {
                if (existing.ExpiresAt > DateTime.UtcNow)
                    return existing;
                _sessionCache.TryRemove(serviceId, out _);
            }

            byte[] context = Encoding.UTF8.GetBytes(serviceId);
            byte[] derivedKey = new byte[32];

            int deriveResult = sdb_derive_session_key(
                masterCredential, masterCredential.Length,
                context, context.Length,
                derivedKey, derivedKey.Length);

            if (deriveResult != 0)
                throw new CryptographicException("Key derivation failed in native layer");

            byte[] nonce = new byte[24];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(nonce);
            }

            var session = new CachedSession
            {
                DerivedKey = derivedKey,
                ExpiresAt = DateTime.UtcNow.AddMinutes(30),
                ServiceNonce = nonce
            };

            _sessionCache[serviceId] = session;
            return session;
        }

        /// <summary>
        /// Constant-time comparison to prevent timing side-channels.
        /// </summary>
        private static bool ConstantTimeEquals(byte[] a, byte[] b)
        {
            if (a.Length != b.Length)
                return false;

            uint diff = 0;
            for (int i = 0; i < a.Length; i++)
            {
                diff |= (uint)(a[i] ^ b[i]);
            }
            return diff == 0;
        }
    }

    /// <summary>
    /// Connection authenticator that bridges managed and native auth layers.
    /// Handles the protocol negotiation for multi-service database clusters.
    /// </summary>
    public class CrossServiceAuthenticator
    {
        private readonly byte[] _masterKey;
        private readonly string _localServiceId;

        public CrossServiceAuthenticator(byte[] masterKey, string localServiceId)
        {
            _masterKey = masterKey ?? throw new ArgumentNullException(nameof(masterKey));
            _localServiceId = localServiceId ?? throw new ArgumentNullException(nameof(localServiceId));
        }

        /// <summary>
        /// Validates an incoming connection from a peer service.
        /// The token format is: [8-byte timestamp][variable payload][32-byte auth tag]
        /// </summary>
        public AuthResult ValidateIncoming(string remoteServiceId, byte[] authToken, byte[] payload)
        {
            if (authToken == null || authToken.Length < 40)
                return AuthResult.Rejected("Token too short");

            // Extract and validate timestamp (first 8 bytes)
            long timestamp = BitConverter.ToInt64(authToken, 0);
            var tokenTime = DateTimeOffset.FromUnixTimeSeconds(timestamp);
            var drift = Math.Abs((DateTimeOffset.UtcNow - tokenTime).TotalSeconds);

            // Allow 5 minute clock drift between services
            if (drift > 300)
                return AuthResult.Rejected("Token expired or clock drift too large");

            // Delegate to native verification
            bool valid = NativeAuthBridge.AuthenticateServiceRequest(
                remoteServiceId, _masterKey, authToken, payload);

            return valid ? AuthResult.Accepted() : AuthResult.Rejected("Verification failed");
        }
    }

    public class AuthResult
    {
        public bool IsAuthenticated { get; private set; }
        public string Reason { get; private set; }

        public static AuthResult Accepted() => new AuthResult { IsAuthenticated = true };
        public static AuthResult Rejected(string reason) => new AuthResult { IsAuthenticated = false, Reason = reason };
    }
}
